        raise ValueError(f"{name} must be a nonblank string")


def _integer(value, name):
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError(f"{name} must be an integer")


def issue_credential(subject: str, expires_at: int, secret: str) -> str:
    _text(subject, "subject")
    _text(secret, "secret")
    _integer(expires_at, "expires_at")
    raw = json.dumps({"exp": expires_at, "sub": subject}, sort_keys=True, separators=(",", ":")).encode("utf-8")
    payload = _encode(raw)
    signature = _encode(hmac.new(secret.encode("utf-8"), payload.encode("ascii"), hashlib.sha256).digest())
    return payload + "." + signature


def read_credential(token: str, now: int, secret: str) -> dict[str, object]:
    _text(secret, "secret")
    _integer(now, "now")
    if not isinstance(token, str):
        raise ValueError("invalid credential")
    try:
        payload, signature = token.split(".")
        expected = _encode(hmac.new(secret.encode("utf-8"), payload.encode("ascii"), hashlib.sha256).digest())
        if not hmac.compare_digest(signature, expected):
            raise ValueError
        claims = json.loads(_decode(payload).decode("utf-8"))
        if not isinstance(claims, dict) or set(claims) != {"exp", "sub"}:
            raise ValueError
        if isinstance(claims["exp"], bool) or not isinstance(claims["exp"], int):
            raise ValueError
        if not isinstance(claims["sub"], str) or not claims["sub"].strip():
            raise ValueError
    except (ValueError, TypeError, UnicodeError, json.JSONDecodeError):
        raise ValueError("invalid credential") from None
    if now > claims["exp"]:
        raise ValueError("expired credential")
    return {"exp": claims["exp"], "sub": claims["sub"]}

